// "Beyond the 66": deuterocanonical and extra-biblical book texts (public domain), generated by
// scripts/gen_extra_books.mjs into backend/public/extra-books/<ID>.json and served here (public, cached).
import { Hono } from 'hono';
import { notFound } from '../lib/http.js';

export const extraBooks = new Hono();

extraBooks.get('/extra-books/:file', async (c) => {
  const file = c.req.param('file');
  if (!/^[A-Z0-9]{2,6}\.json$/.test(file)) throw notFound('Unknown book');
  if (!c.env.ASSETS) throw notFound('Book texts are not available on this server');
  const res = await c.env.ASSETS.fetch(new Request(new URL(`/extra-books/${file}`, c.req.url)));
  if (!res.ok) throw notFound('Unknown book');
  return new Response(res.body, {
    headers: {
      'Content-Type': 'application/json; charset=utf-8',
      // the texts never change for a given build; a day keeps updates possible
      'Cache-Control': 'public, max-age=86400',
    },
  });
});
